"use client";

import { ArrowUpRight } from "lucide-react";
import { useCommerceStore } from "@/lib/commerce-store";

const categories = ["Tout voir", "Canapés", "Matelas", "Fauteuils"];

export function CategorySection() {
  const category = useCommerceStore((state) => state.category);
  const setCategory = useCommerceStore((state) => state.setCategory);

  return (
    <section className="collection-section" id="collections">
      <div className="section-heading"><div><p className="eyebrow">CHOISISSEZ VOTRE PIÈCE</p><h2>Habiter <em>mieux.</em></h2></div><a className="text-link desktop-only" href="/products">Toute la collection <ArrowUpRight size={15} /></a></div>
      <div className="category-list">{categories.map((name, index) => <button key={name} className={category === name ? "category active" : "category"} onClick={() => setCategory(name)}><span className="category-index">0{index + 1}</span><span>{name}</span><span className="category-arrow">↗</span></button>)}</div>
    </section>
  );
}
